proof fn lemma_rotate_left_one<T>(s: Seq<T>, i: int)
    requires
        0 <= i < s.len(),
    ensures
        (s.subrange(i, s.len() as int) + s.subrange(0, i)).subrange(
            1,
            s.len() as int,
        ).push((s.subrange(i, s.len() as int) + s.subrange(0, i))[0])
            == s.subrange(i + 1, s.len() as int) + s.subrange(0, i + 1),
