    assert(before[cursor + 1] == s[cursor + 1]);
    assert_seqs_equal!(after, shifted_right(s, index, cursor + 1), j => {
        if j == cursor {
            assert(after[j] == s[cursor + 1]);
        } else if j == cursor + 1 {
            assert(after[j] == s[index]);
