        let element = v[i].clone();
        assert(cloned::<T>(v@[i as int], element));
        deq.push_back(element);
        i += 1;
    }

    assert(vec_dequeue_clone_trigger(*v, deq));
    assert(v@ =~= deq@ ==> v@ == deq@);
    deq
}

